document.addEventListener("wathba:langchange",t=>{const a=t.detail?.lang;if(!a||a===document.body.dataset.academyLang)return;const n=window.location.pathname.split("/").pop();if(!/^academy(?:-[a-z-]+)?\.html$/.test(n))return;const e=`${n.replace(/-en\.html$/,".html").replace(/\.html$/,"")}${"en"===a?"-en":""}.html${window.location.hash}`;window.location.assign(e)});